#!/usr/bin/env python3
"""R18 arrival-driven formal PG/isolated Worker acceptance; generated bytes only."""
import argparse
from copy import deepcopy
import hashlib
import json
import os
from pathlib import Path
import secrets
import signal
import subprocess
import sys
import time
from urllib.parse import urlencode

import round16_acceptance as r
from round16_supplement import intake, counts
from round18_profile import fixture, at
import bundle
from cpag_core.dual_source import references
from cpag_core.pipeline import canonical
from cpag_core.replay import instant

WORKER_IMAGE=os.environ.get('CPAG_R18_WORKER_IMAGE','cpag-isolated:r18-acceptance')

HASH_FILES=('snapshots.jsonl','revisions.jsonl','analysis.json','events.json','graph.json','metrics.json','arrivals.jsonl')


def hashes(output):return {name:bundle.sha(output/name) for name in HASH_FILES}


def rows(path):return [json.loads(line) for line in path.read_text().splitlines() if line]


def check_prefix(snapshot, config):
    """Only declared arrivals up through this historical step may appear in refs."""
    allowed={}
    for number,step in enumerate(config['replay']['sequence'],1):
        if number>snapshot['arrival_seq']:break
        if 'record_number' in step:
            allowed.setdefault((step['source_slot'],step['record_number']),number)
    for ref in references(snapshot):
        assert 'file_sha256' not in ref
        ordinal=ref['frame_number'] if ref['frame_number'] is not None else ref['record_number']
        assert (ref['source_slot'],ordinal) in allowed,(snapshot['snapshot_number'],ref)
    assert 'file_sha256' not in canonical(snapshot).decode()


def history_answers(snapshot_rows, case):
    pending=next(row for row in snapshot_rows if instant(row['available_at'])==instant(at(10)) and row['analysis']['operations'])
    op=pending['analysis']['operations'][0]
    assert op['replay']['status']=='pending_response' and op['response']['state']=='missing'
    assert len(pending['analysis']['network'])==1 and pending['analysis']['candidates']==[] and pending['analysis']['changes']==[]
    assert pending['graph']['edges']==[]
    revised=next(row for row in snapshot_rows if instant(row['available_at'])==instant(at(13 if case=='allowed_late' else 12)) and row['analysis']['changes'])
    analysis=revised['analysis'];op=analysis['operations'][0]
    assert len(analysis['network'])==2 and len(analysis['changes'])==1
    assert op['response']['state']=='success'
    if case!='response_expired':
        assert op['replay']['status']=='normal' and op['assessment']=='expected_change_observed'
        assert len(analysis['candidates'])==1 and analysis['candidates'][0]['state']=='supported_candidate'
        assert analysis['candidates'][0]['claim']['status']=='hypothetical'
        assert len(revised['graph']['edges'])==1
    else:
        assert op['replay']['status']=='unknown' and op['assessment']=='unknown'
        assert 'response_clock_validity_outside' in op['unknown_reasons']
        assert analysis['candidates']==[] and revised['graph']['edges']==[]
    final=snapshot_rows[-1]['analysis']
    assert len(final['network'])==2 and len(final['process'])==5 and len(final['changes'])==1
    assert final['operations'][0]['replay']['closed'] is True
    assert len(final['candidates'])==(0 if case=='response_expired' else 1)
    return {'pending':pending['snapshot_number'],'revised':revised['snapshot_number'],
            'final':snapshot_rows[-1]['snapshot_number'],'operation_id':op['operation_id'],
            'change_id':analysis['changes'][0]['event_id']}


def check_metrics(metrics, case):
    event=metrics['event_latency'];confirmation=metrics['confirmation_latency']
    assert event['denominator_total_events']==7
    assert event['denominator_computable_events']==(6 if case=='response_expired' else 7)
    assert confirmation['denominator_candidates']==(0 if case=='response_expired' else 1)
    if case!='response_expired':
        assert confirmation['samples'][0]['latency_seconds']==([3.0,3.0] if case=='allowed_late' else [2.0,2.0])
    samples=metrics['backlog']['samples'];assert samples
    for row in samples:
        assert row['waiting_operations']==row['prerequisite_waiting_operations']
        assert row['open_window_operations']>=row['prerequisite_waiting_operations']>=0
    if case!='response_expired':
        when=at(13 if case=='allowed_late' else 12)
        ready=next(row for row in samples if instant(row['available_at'])==instant(when))
        assert ready['prerequisite_waiting_operations']==0 and ready['open_window_operations']==1
    assert samples[-1]['open_window_operations']==0


def check_run(client, job, root, attempt, config, case):
    output=root/'jobs'/job/f'attempt-{attempt}'
    snapshots=rows(output/'snapshots.jsonl');revisions=rows(output/'revisions.jsonl')
    check_metrics(json.loads((output/'metrics.json').read_text()),case)
    assert revisions
    for snapshot in snapshots:check_prefix(snapshot,config)
    answer=history_answers(snapshots,case)
    result=client.expect('GET',f'/api/v3/runs/{job}/result')
    assert result['data']['analysis']==json.loads((output/'analysis.json').read_text())
    history=client.expect('GET',f'/api/v3/runs/{job}/revisions?after=0&limit=100')
    assert history['revisions']==revisions
    for label in ('pending','revised','final'):
        number=answer[label];actual=client.expect('GET',f'/api/v3/runs/{job}/snapshots/{number}')
        assert actual==snapshots[number]
        graph=client.expect('GET',f'/api/v3/runs/{job}/graph?revision={number}')
        assert graph['graph']==actual['graph']
        assert graph['mode']=='dual_source_replay' and graph['replay_version']==config['replay']['version']
        assert graph['revision_number']==actual['revision_number']
    final_graph=client.expect('GET',f'/api/v3/runs/{job}/graph')
    assert final_graph['graph']==snapshots[-1]['graph']
    assert final_graph['mode']=='dual_source_replay' and final_graph['replay_version']==config['replay']['version']
    pending=client.expect('GET',f'/api/v3/runs/{job}/evidence?'+urlencode({'revision':answer['pending'],'operation':answer['operation_id']}))
    assert len(pending['verified_original_evidence'])==1 and len(pending['verified_network_fields'])==1
    assert pending['verified_original_evidence'][0]['source_ref']['source_slot']=='network-0'
    assert pending['verified_original_evidence'][0]['source_ref']['frame_number']==1
    for number in (answer['pending'],answer['revised']):
        trigger=client.expect('GET',f'/api/v3/runs/{job}/evidence?'+urlencode({'revision':number,'trigger':'true'}))
        expected=snapshots[number]['trigger']['evidence_refs']
        assert trigger['selection']['trigger']==snapshots[number]['trigger']
        assert len(trigger['verified_original_evidence'])==1
        assert [item['source_ref'] for item in trigger['verified_original_evidence']]==expected
        if number==answer['revised']:
            original=trigger['verified_original_evidence'][0]
            assert original['source_ref']['source_slot']=='process' and original['source_ref']['record_number']==4
            assert original['original']['pump']=='1'
    selected=client.expect('GET',f'/api/v3/runs/{job}/evidence?'+urlencode({'revision':answer['revised'],'operation':answer['operation_id']}))
    changed=client.expect('GET',f'/api/v3/runs/{job}/evidence?'+urlencode({'revision':answer['revised'],'change':answer['change_id']}))
    assert len(changed['verified_original_evidence'])==2
    assert {row['source_ref']['record_number'] for row in changed['verified_original_evidence']}=={3,4}
    if case!='response_expired':assert len(selected['verified_original_evidence'])==4
    else:assert len(selected['verified_original_evidence'])==2
    for response in (pending,selected,changed):
        for entry in response['verified_original_evidence']:
            assert 'file_sha256' not in entry['source_ref']
            assert entry['source_ref']['record_sha256']
    artifacts=client.expect('GET',f'/api/v3/runs/{job}/artifacts')['artifacts']
    for name in ('snapshots.jsonl','revisions.jsonl','analysis.json'):
        entry=next(row for row in artifacts if row['path']==name)
        data=client.expect('GET',f'/api/v3/runs/{job}/artifacts/{name}/download')
        assert isinstance(data,bytes) and hashlib.sha256(data).hexdigest()==entry['sha256']
    return {**answer,'hashes':hashes(output),'snapshot_count':len(snapshots),'revision_count':len(revisions),
            'pending_original_refs':1,'normal_operation_original_refs':2 if case=='response_expired' else 4,
            'change_original_refs':2,'pending_trigger_refs':1,'revised_trigger_refs':1}


def main(work, serve=False):
    work.mkdir(parents=True,mode=0o700,exist_ok=False);(work/'public').mkdir()
    source=work/'source';source.mkdir();control=work/'control';control.mkdir()
    restored=work/'restored';restore_control=work/'restore-control';restore_control.mkdir()
    static_root=Path(os.environ.get('CPAG_STATIC_ROOT',str(r.REPO/'webui/out'))).resolve()
    container='cpag-r18-'+secrets.token_hex(4)
    pg,port,internal,rport,rinternal=[r.port() for _ in range(5)]
    env=dict(os.environ,PYTHONPATH=os.pathsep.join([str(r.REPO/'services/worker'),str(r.REPO/'services/analysis/src')]),
             GOCACHE=os.environ.get('GOCACHE','/tmp/cpag-go-build'),GOMODCACHE=os.environ.get('GOMODCACHE','/tmp/cpag-go-mod'))
    report={'scope':'generated synthetic replay engineering only; not industrial or R19 throughput validation','status':'running','checks':{}}
    app=worker=restored_app=None;created=False
    try:
        r.build(work,env,skip_image_build=True)
        r.run('docker','run','--name',container,'-d','-e','POSTGRES_DB=m4_validation','-e','POSTGRES_PASSWORD=m4-disposable-only',
              '-p',f'127.0.0.1:{pg}:5432',r.PG_IMAGE,stdout=subprocess.DEVNULL);created=True
        for _ in range(150):
            if subprocess.run(['docker','exec',container,'pg_isready','-h','127.0.0.1','-U','postgres','-d','m4_validation'],capture_output=True).returncode==0:break
            time.sleep(.1)
        else:raise RuntimeError('database readiness timeout')
        for migration in sorted((r.REPO/'internal/jobs/migrations').glob('*.sql')):
            with migration.open('rb') as stream:bundle.pg(container,'m4_validation','psql','-v','ON_ERROR_STOP=1',stdin=stream,stdout=subprocess.DEVNULL)
        username='r18-admin';password=secrets.token_urlsafe(24);wt=secrets.token_urlsafe(32);ct=secrets.token_urlsafe(32)
        config=r.make_config(pg,'m4_validation',source,control,port,internal,wt,ct,username,password,static_root);config['static_root']=str(static_root)
        app=r.start_app(work,'app',work/'cpagx-v3',config);client=r.Client(f'http://127.0.0.1:{port}')
        client.expect('POST','/api/v3/session',{'username':username,'password':password})
        replay_page=client.expect('GET','/replay')
        assert isinstance(replay_page,bytes) and '双源顺序回放'.encode() in replay_page
        report['checks']['fresh_static_replay_route']=True
        r.cli_request(work/'cpagctl',work,client.origin,username,password,'/api/v3/datasets')
        worker_cfg=work/'worker.json';r.write_private(worker_cfg,{'api_url':f'http://127.0.0.1:{internal}',
            'shared_root':str(source),'control_root':str(control),'worker_token':wt,'coordinator_token':ct,
            'worker_id':'r18-worker','image':WORKER_IMAGE,'poll_seconds':.2,'recovery_seconds':2})
        worker=r.start_worker(work,'worker',worker_cfg,env)
        def save(ds,kind,document):return client.expect('POST',f'/api/v3/datasets/{ds}/configs',{'kind':kind,'document':document},code=201)['config']['id']
        cases={}
        for case in ('normal','response_expired','allowed_late'):
            networks,process,path,profile=fixture(work/'fixtures'/case,case=case)
            name={'normal':'R18 normal arrival replay','response_expired':'R18 response clock unknown','allowed_late':'R18 allowed late revision'}[case]
            ds=client.expect('POST','/api/v3/datasets',{'name':name,'source_kind':'synthetic','source':'generated arrival fixture',
                'batch':'round18','authorization_ref':'repository generated software fixture'},code=201)['dataset']['id']
            for number,network in enumerate(networks):r.upload(client,ds,'network',network,f'{case}-network-{number}')
            r.upload(client,ds,'process',process,f'{case}-process')
            intake_id=save(ds,'intake',intake(ds))
            preflight=client.expect('POST',f'/api/v3/datasets/{ds}/preflight',{'config_version_id':intake_id})['preflight_id']
            profile_id=save(ds,'dual',profile)
            cases[case]={'dataset_id':ds,'dataset_name':name,'preflight_id':preflight,'config_id':profile_id,
                         'profile':profile,'networks':networks,'process':process,'profile_path':path,'runs':[]}
        def submit(case,config_id=None):
            meta=cases[case]
            return client.expect('POST','/api/v3/runs',{'dataset_id':meta['dataset_id'],'config_version_id':config_id or meta['config_id'],
                'preflight_id':meta['preflight_id'],'mode':'dual_source_replay'},code=201)['run']['id']
        verified=[]
        for case,repeats in [('normal',3),('response_expired',1),('allowed_late',1)]:
            for _ in range(repeats):
                job=submit(case);status=r.status_until(client,job);assert status['state']=='succeeded',status
                checked=check_run(client,job,source,status['attempt'],cases[case]['profile'],case)
                checked.update(run_id=job,case=case);verified.append(checked);cases[case]['runs'].append(job)
        normal=[row for row in verified if row['case']=='normal']
        assert normal[0]['hashes']==normal[1]['hashes']==normal[2]['hashes']
        report['checks']['three_isolated_worker_semantic_hashes']=[row['hashes'] for row in normal]
        for case in ('normal','response_expired','allowed_late'):
            meta=cases[case];job=meta['runs'][0]
            payload=json.loads(bundle.pg(container,'m4_validation','psql','-X','-qAt','-c',f"SELECT payload::text FROM m4_jobs WHERE id='{job}'",capture_output=True,text=True).stdout)
            output=work/f'cli-{case}';args=[sys.executable,'-m','cpag_core.replay_export']
            for ref in payload.get('networks',[payload['network']]):args+=['--network',str(source/ref['path'])]
            args+=['--process',str(meta['process']),'--profile',str(meta['profile_path']),'--output',str(output)]
            r.run(*args,env=env,capture_output=True)
            expected=next(row for row in verified if row['run_id']==job)['hashes']
            assert hashes(output)==expected
            assert r.cli_call(work/'cpagctl',work,client.origin,'GET',f'/api/v3/runs/{job}/result')==client.expect('GET',f'/api/v3/runs/{job}/result')
        report['checks']['cli_worker_api_parity']=True
        late=next(row for row in verified if row['case']=='allowed_late')
        late_metrics=json.loads((source/'jobs'/late['run_id']/'attempt-1'/'metrics.json').read_text())
        assert late_metrics['counts']['late']>=1
        report['checks']['allowed_late_real_worker_revision']={'run_id':late['run_id'],'metrics':late_metrics}
        paced=[]
        for speed in (1,10):
            profile=deepcopy(cases['normal']['profile']);profile['replay'].update(speed=speed,realtime=True)
            profile_id=save(cases['normal']['dataset_id'],'dual',profile)
            job=submit('normal',profile_id);status=r.status_until(client,job);assert status['state']=='succeeded',status
            checked=check_run(client,job,source,status['attempt'],profile,'normal');assert checked['hashes']==normal[0]['hashes']
            runtime=json.loads((source/'jobs'/job/f"attempt-{status['attempt']}"/'runtime_metrics.json').read_text())
            assert runtime['paced'] is True and runtime['speed']==speed and runtime['samples']
            assert runtime['elapsed_seconds'] >= (9.5 if speed==1 else .9)
            paced.append({'speed':speed,'run_id':job,'runtime_metrics':runtime,'semantic_hashes':checked['hashes']})
            verified.append({**checked,'run_id':job,'case':'normal','paced_speed':speed})
        report['checks']['actual_1x_10x_same_simulation_semantics']=paced
        report['checks']['normal_simulation_metrics']=json.loads((source/'jobs'/normal[0]['run_id']/'attempt-1'/'metrics.json').read_text())
        viewer='r18-viewer';viewer_password=secrets.token_urlsafe(24)
        viewer_id=client.expect('POST','/api/v3/users',{'username':viewer,'password':viewer_password,'role':'viewer'},code=201)['user']['id']
        for meta in cases.values():client.expect('POST',f"/api/v3/datasets/{meta['dataset_id']}/acl",{'user_id':viewer_id,'access':'viewer'})
        readonly=r.Client(client.origin);readonly.expect('POST','/api/v3/session',{'username':viewer,'password':viewer_password})
        before=counts(container)
        assert readonly.expect('GET',f"/api/v3/datasets/{cases['normal']['dataset_id']}")['dataset']['id']==cases['normal']['dataset_id']
        denied_code,denied=readonly.request('POST','/api/v3/runs',{'dataset_id':cases['normal']['dataset_id'],'config_version_id':cases['normal']['config_id'],
            'preflight_id':cases['normal']['preflight_id'],'mode':'dual_source_replay'})
        assert denied_code in (403,404) and denied['error']['code'] in ('forbidden','not_found')
        assert counts(container)==before
        first=normal[0];readonly.expect('GET',f"/api/v3/runs/{first['run_id']}/snapshots/{first['pending']}")
        report['checks']['viewer_read_allowed_write_denied']={'read_allowed':True,'write_status':denied_code,'write_error':denied['error']['code'],'job_counts_unchanged':True}
        r.stop(worker);worker=None;r.stop(app);app=None
        snapshot=bundle.backup(container,'m4_validation',source,work/'bundle');assert snapshot['catalog_audit']['valid']
        audit=bundle.restore(container,work/'bundle',restored);assert audit['valid'] and audit['catalog_equal'] and audit['attempt_history_equal']
        restore_config=r.make_config(pg,'m4_restore_validation',restored,restore_control,rport,rinternal,wt,ct,username,password,static_root);restore_config['static_root']=str(static_root)
        restored_app=r.start_app(work,'restored-app',work/'cpagx-v3',restore_config)
        restored_client=r.Client(f'http://127.0.0.1:{rport}');restored_client.expect('POST','/api/v3/session',{'username':username,'password':password})
        for original in verified:
            profile=cases[original['case']]['profile'];status=restored_client.expect('GET',f"/api/v3/runs/{original['run_id']}")['run']
            actual=check_run(restored_client,original['run_id'],restored,status['attempt'],profile,original['case'])
            assert actual['hashes']==original['hashes']
        report['checks']['all_terminal_replay_history_empty_database_new_directory_restore']=True
        app=r.start_app(work,'app-restarted',work/'cpagx-v3',config);worker=r.start_worker(work,'worker-restarted',worker_cfg,env)
        report.update(status='passed',runs=verified,static_root=str(static_root),worker_image=WORKER_IMAGE)
        (work/'public/results.json').write_text(json.dumps(report,indent=2)+'\n')
        unknown=next(row for row in verified if row['case']=='response_expired')
        r.write_private(work/'state.json',{'url':client.origin+'/workspace/','restored_url':restored_client.origin+'/workspace/',
            'username':username,'password':password,'viewer_username':viewer,'viewer_password':viewer_password,
            'normal':{**first,'dataset_name':cases['normal']['dataset_name'],'dataset_id':cases['normal']['dataset_id'],
                      'config_id':cases['normal']['config_id'],'preflight_id':cases['normal']['preflight_id']},
            'unknown':{**unknown,'dataset_name':cases['response_expired']['dataset_name']}})
        if serve:
            stopping=False
            def stop_serving(*_):
                nonlocal stopping
                stopping=True
            signal.signal(signal.SIGTERM,stop_serving);signal.signal(signal.SIGINT,stop_serving)
            while not stopping:
                if any(process.poll() is not None for process in (app,worker,restored_app)):raise RuntimeError('served replay environment exited')
                time.sleep(.5)
    finally:
        r.stop(worker);r.stop(app);r.stop(restored_app)
        if created:subprocess.run(['docker','rm','-f',container],capture_output=True)


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--output',type=Path,required=True);parser.add_argument('--serve',action='store_true')
    args=parser.parse_args();main(args.output.resolve(),args.serve)
